type Receipt = { state: "verified" | "pending_verification" | string; operation_id: string; result_version: number; changes: Change[]; before: unknown; after: unknown; duplicate?: boolean; current_revision?: number; undo_of?: string; raw_text?: string; occurred_at?: string; created_at?: string; source_event_id?: string };
