    catch (error) { if (fallback) { setReceipt({ ...fallback, state: "pending_verification" }); setNotice({ kind: "warning", title: "已收到保存响应，读回仍待验证", detail: `操作 ${operationId}。请查询该编号，不要重新创建任务。${errorText(error)}` }); return false; } throw error; }
