    if (await saveChanges([{ type: "project", ...(editingProject.id ? { id: editingProject.id } : {}), values: { name: editingProject.name?.trim(), goal: editingProject.goal?.trim(), status: editingProject.status, external_links: links } }], `人工${editingProject.id ? "更新" : "新建"}项目：${editingProject.name}`)) setEditingProject(null);
